window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1347ed459cf97267"]={"versions": [{"id": "FIG-1347ed459cf97267", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Spezifikationsübersicht zur Header- und Segmentstruktur im Kontext des AUTOSAR SOME/IP Transport Protocol (SOME/IP-TP). Das Diagramm veranschaulicht anhand eines konkreten Beispiels die Aufteilung einer Gesamt-Nutzlast in mehrere segmentierte SOME/IP-Nachrichten über die Protokollfelder Length, Message Type, Offset Value und More Segment Flag.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Tabelle definiert vier Spalten für die SOME/IP- und TP-Header-Attribute je übertragenem Datensegment:</p>\n<ul class=\"fig-list\">\n<li>Length (Bytes): Berechnungsformel und Summe der Segmentlänge, aufgeteilt in SOME/IP-Header-Restanteil (8 Bytes), TP-Zusatzheader (4 Bytes) und Segment-Payload (1392 bzw. 312 Bytes).</li>\n<li>Message Type [TP-Flag]: Kennzeichnung des gesetzten TP-Bits (<code>TP-Flag = '1'</code>).</li>\n<li>Offset Value: Vielfaches von 16 Bytes zur Lokalisierung der Nutzlastdaten im Gesamtdatenstrom (Werte 0, 87, 174, 261, 348).</li>\n<li>More Segment Flag: Bitflag zur Signalisierung nachfolgender Segmente (1 für Folgesegmente, 0 für das Endsegment).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzielle Fragmentierung einer 5880-Byte-Nutzlast über fünf aufeinanderfolgende SOME/IP-TP-Pakete:</p>\n<ol class=\"fig-list\">\n<li>Segment 1: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 0, More Segment Flag = 1.</li>\n<li>Segment 2: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 87 (entspricht 87 * 16 = 1392 Bytes), More Segment Flag = 1.</li>\n<li>Segment 3: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 174 (2784 Bytes), More Segment Flag = 1.</li>\n<li>Segment 4: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 261 (4176 Bytes), More Segment Flag = 1.</li>\n<li>Segment 5 (Schlusssegment): Length = 8 + 4 + 312 = 324 Bytes, Offset = 348 (5568 Bytes), More Segment Flag = 0.</li>\n</ol>\n<p class=\"fig-p\">Der Empfänger assembliert die Segmente anhand des stetig steigenden Offsets, bis das Flag 0 das Ende der Übertragung anzeigt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung des SOME/IP-TP-Senders und -Empfängers:</p>\n<ul class=\"fig-list\">\n<li>Das SOME/IP-Längenfeld beinhaltet ab Position Request ID den Rest des SOME/IP-Headers (8 Bytes), den 4-Byte-TP-Header sowie die Nutzlast des aktuellen Segments.</li>\n<li>Das TP-Flag im Message Type muss für alle transportierten Segmente auf 1 gesetzt sein.</li>\n<li>Sämtliche Zwischensegmente müssen bezüglich der Nutzlast ein Vielfaches von 16 Bytes umfassen; der Offset-Wert wird in 16-Byte-Einheiten kodiert (<code>Offset = ByteOffset / 16</code>).</li>\n<li>Das letzte Segment darf eine nicht durch 16 teilbare Restlänge aufweisen und muss zwingend <code>More Segment Flag = 0</code> tragen.</li>\n</ul>"}, {"id": "FIG-31282e2500ba77ea", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Spezifikationsübersicht zur Header- und Segmentstruktur im Kontext des AUTOSAR SOME/IP Transport Protocol (SOME/IP-TP). Das Diagramm veranschaulicht anhand eines konkreten Beispiels die Aufteilung einer Gesamt-Nutzlast in mehrere segmentierte SOME/IP-Nachrichten über die Protokollfelder Length, Message Type, Offset Value und More Segment Flag.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Tabelle definiert vier Spalten für die SOME/IP- und TP-Header-Attribute je übertragenem Datensegment:</p>\n<ul class=\"fig-list\">\n<li>Length (Bytes): Berechnungsformel und Summe der Segmentlänge, aufgeteilt in SOME/IP-Header-Restanteil (8 Bytes), TP-Zusatzheader (4 Bytes) und Segment-Payload (1392 bzw. 312 Bytes).</li>\n<li>Message Type [TP-Flag]: Kennzeichnung des gesetzten TP-Bits (<code>TP-Flag = '1'</code>).</li>\n<li>Offset Value: Vielfaches von 16 Bytes zur Lokalisierung der Nutzlastdaten im Gesamtdatenstrom (Werte 0, 87, 174, 261, 348).</li>\n<li>More Segment Flag: Bitflag zur Signalisierung nachfolgender Segmente (1 für Folgesegmente, 0 für das Endsegment).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzielle Fragmentierung einer 5880-Byte-Nutzlast über fünf aufeinanderfolgende SOME/IP-TP-Pakete:</p>\n<ol class=\"fig-list\">\n<li>Segment 1: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 0, More Segment Flag = 1.</li>\n<li>Segment 2: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 87 (entspricht 87 * 16 = 1392 Bytes), More Segment Flag = 1.</li>\n<li>Segment 3: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 174 (2784 Bytes), More Segment Flag = 1.</li>\n<li>Segment 4: Length = 8 + 4 + 1392 = 1404 Bytes, Offset = 261 (4176 Bytes), More Segment Flag = 1.</li>\n<li>Segment 5 (Schlusssegment): Length = 8 + 4 + 312 = 324 Bytes, Offset = 348 (5568 Bytes), More Segment Flag = 0.</li>\n</ol>\n<p class=\"fig-p\">Der Empfänger assembliert die Segmente anhand des stetig steigenden Offsets, bis das Flag 0 das Ende der Übertragung anzeigt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Implementierung des SOME/IP-TP-Senders und -Empfängers:</p>\n<ul class=\"fig-list\">\n<li>Das SOME/IP-Längenfeld beinhaltet ab Position Request ID den Rest des SOME/IP-Headers (8 Bytes), den 4-Byte-TP-Header sowie die Nutzlast des aktuellen Segments.</li>\n<li>Das TP-Flag im Message Type muss für alle transportierten Segmente auf 1 gesetzt sein.</li>\n<li>Sämtliche Zwischensegmente müssen bezüglich der Nutzlast ein Vielfaches von 16 Bytes umfassen; der Offset-Wert wird in 16-Byte-Einheiten kodiert (<code>Offset = ByteOffset / 16</code>).</li>\n<li>Das letzte Segment darf eine nicht durch 16 teilbare Restlänge aufweisen und muss zwingend <code>More Segment Flag = 0</code> tragen.</li>\n</ul>"}], "trans": [{"from": "FIG-1347ed459cf97267", "to": "FIG-31282e2500ba77ea", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
